package mx.com.mesaregia.inventario.application.service.impl;
import mx.com.mesaregia.inventario.application.service.AlertaInventarioQueryService; import mx.com.mesaregia.inventario.api.response.AlertaInventarioResponse; import mx.com.mesaregia.inventario.domain.enums.TipoAlertaInventario; import mx.com.mesaregia.inventario.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service
public class AlertaInventarioQueryServiceImpl implements AlertaInventarioQueryService {
 private final ExistenciaRepository er; private final LimiteInventarioRepository lr; public AlertaInventarioQueryServiceImpl(ExistenciaRepository e,LimiteInventarioRepository l){er=e;lr=l;}
 @Override @Transactional(readOnly=true) public List<AlertaInventarioResponse> consultar(Long almacen, TipoAlertaInventario filtro){ var out=new ArrayList<AlertaInventarioResponse>(); for(var e:er.findAllByAlmacenIdOrderByIdProductoExterno(almacen)){ var l=lr.findByExistenciaId(e.getId()).orElse(null); if(l==null) continue; TipoAlertaInventario t=null; int dif=0; if(e.getExistenciaFisica()<=l.getMinimo()){t=TipoAlertaInventario.BAJO_MINIMO;dif=l.getMinimo()-e.getExistenciaFisica();} else if(e.getExistenciaFisica()>=l.getMaximo()){t=TipoAlertaInventario.SOBRE_MAXIMO;dif=e.getExistenciaFisica()-l.getMaximo();} if(t!=null&&(filtro==null||filtro==t)) out.add(new AlertaInventarioResponse(e.getId(),e.getIdProductoExterno(),almacen,t,e.getExistenciaFisica(),l.getMinimo(),l.getMaximo(),dif,e.getActualizadoEn())); } return out; }
}
